13	/**
14	 * Translates between the CLI's JSON wire representation and living cells.
15	 * Owns the "aliveCells" key, the [x, y] pair encoding, and the emitted cell order.
16	 */
17	class AliveCellsJson {
18	
19	    private static final String ALIVE_CELLS = "aliveCells";
20	
21	    private static final Comparator<Cell> EMITTED_ORDER =
22	            Comparator.comparingInt(Cell::x).thenComparingInt(Cell::y);
23	
24	    private final ObjectMapper objectMapper = new ObjectMapper();
25	
26	    Set<Cell> readAliveCells(InputStream input) throws IOException {
27	        JsonNode request = objectMapper.readTree(input);
28	        Set<Cell> aliveCells = new LinkedHashSet<>();
29	        for (JsonNode cell : request.get(ALIVE_CELLS)) {
30	            aliveCells.add(new Cell(cell.get(0).asInt(), cell.get(1).asInt()));
31	        }
32	        return aliveCells;
33	    }
34	
35	    void writeAliveCells(OutputStream output, Set<Cell> aliveCells) throws IOException {
36	        ObjectNode response = objectMapper.createObjectNode();
37	        ArrayNode cells = response.putArray(ALIVE_CELLS);
38	        aliveCells.stream()
39	                .sorted(EMITTED_ORDER)
40	                .forEach(cell -> cells.addArray().add(cell.x()).add(cell.y()));
41	        objectMapper.writeValue(output, response);
42	    }
43	}
