import gameoflife.Cell;
import gameoflife.GameOfLife;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.UncheckedIOException;
import java.util.Set;

public class GameOfLifeCli {

    private final AliveCellsJson aliveCellsJson = new AliveCellsJson();

    public void run(InputStream input, OutputStream output) {
        try {
            Set<Cell> aliveCells = aliveCellsJson.readAliveCells(input);
            Set<Cell> nextGeneration = new GameOfLife().nextGeneration(aliveCells);
            aliveCellsJson.writeAliveCells(output, nextGeneration);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
